package com.delivery.platform.delivery.infrastructure;import com.delivery.platform.delivery.application.CourierAssignmentStrategy;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Component;import java.util.*;@Component public class BasicCourierAssignmentStrategy implements CourierAssignmentStrategy{private final JdbcClient db;public BasicCourierAssignmentStrategy(JdbcClient db){this.db=db;}public Optional<UUID> select(UUID t,UUID b,UUID z){return db.sql("select c.id from courier_profiles c join courier_availability a on a.courier_id=c.id where c.tenant_id=:t and c.status='ACTIVE' and a.status='ONLINE' and (a.branch_id is null or a.branch_id=:b) and (a.zone_id is null or a.zone_id=:z) and c.current_active_deliveries<c.max_active_deliveries order by a.updated_at,c.current_active_deliveries limit 1").param("t",t).param("b",b).param("z",z).query(UUID.class).optional();}}
